// initEncryption builds the Encryptor used by the repository layer to encrypt/decrypt
// stored credentials. An empty encKeyHex is a supported "encryption off" configuration
// (see config/dev.yaml) — it degrades to NoOpEncryptor instead of failing startup, and
// the resulting insecure mode is surfaced to operators via a warning log and to the
// frontend via GetConfig.CredsEncrypted (see auth_api.NewAuthImpl).
func initEncryption(encKeyHex string) (cryptoutil.Encryptor, error) {
	if encKeyHex == "" {
		log.Warn().Msg(
			"ENVIRONMENT_CREDS_ENCRYPTION_KEY is not set — running in INSECURE mode, " +
				"all credentials will be stored as plain text",
		)

		return cryptoutil.NoOpEncryptor{}, nil
	}

	encKey, err := hex.DecodeString(encKeyHex)
	if err != nil {
		return nil, rerrors.Wrap(err, "error decoding creds_encryption_key")
	}

	encryptor, err := cryptoutil.NewAESEncryptor(encKey)
	if err != nil {
		return nil, rerrors.Wrap(err, "error creating AES encryptor")
	}

	return encryptor, nil
}

// ensureSetupToken regenerates and logs the one-time first-run setup token when instance setup
// hasn't completed yet — this is the only way an operator learns the token, since it's never
// persisted in plaintext (see SystemSettings.SetupTokenHash). Safe to call on every startup: once
// setup completes, CurrentStatus reports SetupCompleted == true and this becomes a no-op.
func ensureSetupToken(ctx context.Context, setupWizardSvc service.SetupWizardService) error {
	settings, err := setupWizardSvc.CurrentStatus(ctx)
	if err != nil {
		return rerrors.Wrap(err, "error getting setup wizard status")
	}

	if settings.SetupCompleted {
		return nil
	}

	setupToken, err := setupWizardSvc.RegenerateSetupToken(ctx)
	if err != nil {
		return rerrors.Wrap(err, "error regenerating setup token")
	}

	log.Warn().Msgf(
		"first-run setup token: %s — open the setup wizard and enter this token to finish "+
			"configuring the instance. If you lose it, find it again via: "+
			"docker logs <container> | grep \"setup token:\"",
		setupToken,
	)

	return nil
}

// Start - launch custom handlers
// Even if you won't use it keep it for proper work
func (c *Custom) Start(ctx context.Context) error {
	log.Info().Msg("starting server")

	err := c.Transport.Start()
	if err != nil {
		return rerrors.Wrap(err, "error starting server")
	}

	return nil
}

// Stop - gracefully stop custom handlers
// Even if you won't use it keep it for proper work
func (c *Custom) Stop() error {
	err := c.Transport.Stop()
	if err != nil {
		return rerrors.Wrap(err, "error stopping server")
	}
	return nil
}
